DROP TABLE IF EXISTS `categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `categories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `parent_id` int(11) DEFAULT 0,
  `image` varchar(500) DEFAULT NULL,
  `icon` varchar(100) DEFAULT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `display_order` int(11) DEFAULT 0,
  `is_featured` tinyint(1) DEFAULT 0,
  `level` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `desktop_menu_status` enum('show','hide') NOT NULL DEFAULT 'show' COMMENT 'Desktop top menu: show/hide',
  `desktop_menu_order` int(11) NOT NULL DEFAULT 0 COMMENT 'Desktop top menu sort order',
  `desktop_menu_view` enum('yes','no') NOT NULL DEFAULT 'no' COMMENT 'Show design view in desktop top menu?',
  `desktop_menu_design` varchar(50) NOT NULL DEFAULT '' COMMENT 'Desktop top menu design type key',
  `desktop_menu_tag` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tag label shown in desktop menu (sub/sub-sub only)',
  `desktop_menu_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Image shown in desktop top menu dropdown',
  `desktop_home_show` enum('yes','no') NOT NULL DEFAULT 'no' COMMENT 'Show on desktop home page?',
  `desktop_home_design` varchar(50) NOT NULL DEFAULT '' COMMENT 'Desktop home design type (design1/design2/design3/design4)',
  `desktop_home_order` int(11) NOT NULL DEFAULT 0 COMMENT 'Desktop home page sort order',
  `desktop_bg_color` varchar(20) NOT NULL DEFAULT '' COMMENT 'Desktop category background color (#hex)',
  `desktop_bg_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Desktop category background image path',
  `desktop_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Desktop category image (design-dependent)',
  `mobile_topbar_status` enum('show','hide') NOT NULL DEFAULT 'show' COMMENT 'Mobile top bar: show/hide',
  `mobile_topbar_order` int(11) NOT NULL DEFAULT 0 COMMENT 'Mobile top bar sort order',
  `mobile_menu_view` enum('yes','no') NOT NULL DEFAULT 'no' COMMENT 'Show design view in mobile menu?',
  `mobile_menu_design` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mobile menu design type (2 types)',
  `mobile_sidebar_order` int(11) NOT NULL DEFAULT 0 COMMENT 'Mobile sidebar sort order',
  `mobile_home_show` enum('yes','no') NOT NULL DEFAULT 'no' COMMENT 'Show on mobile home page?',
  `mobile_home_design` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mobile home design type (design1/design2/design3/design4)',
  `mobile_home_format` enum('4','6','8') NOT NULL DEFAULT '4' COMMENT 'Mobile home: 4/6/8 image product boxes',
  `mobile_home_order` int(11) NOT NULL DEFAULT 0 COMMENT 'Mobile home page sort order',
  `mobile_bg_color` varchar(20) NOT NULL DEFAULT '' COMMENT 'Mobile category background color (#hex)',
  `mobile_bg_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mobile category background image path',
  `mobile_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mobile category image (design-dependent)',
  `meta_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'SEO meta title',
  `meta_keywords` text DEFAULT NULL COMMENT 'SEO meta keywords',
  `meta_description` text DEFAULT NULL COMMENT 'SEO meta description',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `parent_id` (`parent_id`),
  KEY `status` (`status`),
  KEY `display_order` (`display_order`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
